import{_ as a,o,c as n,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Plugins de ejemplo","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/examples.md","filePath":"es-ES/dev-guide/examples.md","lastUpdated":1785579413000}'),r={name:"es-ES/dev-guide/examples.md"};function s(c,e,l,d,t,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="plugins-de-ejemplo" tabindex="-1">Plugins de ejemplo <a class="header-anchor" href="#plugins-de-ejemplo" aria-label="Permalink to &quot;Plugins de ejemplo&quot;">​</a></h1><p>Dos plugins se distribuyen con el propio SwiftList y son referencias útiles del mundo real — ambos residen en la carpeta <code>Plugins/</code> del repositorio de SwiftList.</p><h2 id="coreextensions-—-acciones-y-el-menu-contextual-del-shell" tabindex="-1">CoreExtensions — acciones y el menú contextual del shell <a class="header-anchor" href="#coreextensions-—-acciones-y-el-menu-contextual-del-shell" aria-label="Permalink to &quot;CoreExtensions — acciones y el menú contextual del shell&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code> implementa tres interfaces a la vez: <code>IPlugin</code>, <code>IActionProvider</code> e <code>IConfigurable</code>.</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> devuelve diez <code>ISearchResultAction</code> integradas — abrir, localizar en el Explorador, copiar ruta, copiar/cortar el propio archivo, abrir un símbolo del sistema en su ubicación, crear archivo/carpeta, y variantes elevadas (ejecutar como administrador) de abrir y símbolo del sistema.</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> devuelve un único <code>IDynamicActionProvider</code> — <code>ShellMenuActionProvider</code> — que es lo que hace que el menú contextual real de Windows (incluidos submenús en cascada anidados como &quot;Enviar a&quot;) aparezca dentro del propio menú de Acciones de SwiftList. Este es el patrón que hay que copiar si quieres mostrar <em>cualquier</em> menú externo generado dinámicamente dentro de SwiftList en lugar de una lista fija de acciones.</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> muestra un esquema de configuración con grupos de campos anidados y un tipo de campo <code>StringList</code> — merece la pena leerlo si tu propio plugin necesita algo más que una lista plana de booleanos en su cuadro de configuración de Configuración → Plugins.</li><li><code>FavoritesTabProvider</code> y <code>HistoryTabProvider</code> implementan cada uno <a href="./sdk/ui-extensions.html#istartuppaneltabprovider"><code>IStartupPanelTabProvider</code></a> para mostrar sus listas existentes como pestañas en el <a href="./../user-guide/settings/startup-panel.html">Panel de Inicio</a> — una referencia mínima para esa interfaz, ya que ambos simplemente envuelven una lista de elementos ya consultada, sin estado adicional propio.</li><li><code>FavoritesSourceProvider</code> y <code>WindowsRecentSourceProvider</code> hacen lo mismo para <a href="./sdk/ui-extensions.html#iquickpanelsourceprovider"><code>IQuickPanelSourceProvider</code></a>, y entre los dos cubren ambos extremos de esa interfaz: el primero devuelve tal cual una lista que ya está en memoria, mientras que el segundo lee un directorio y resuelve accesos directos del shell por COM en una tarea en segundo plano, recorta el conjunto antes de hacer la parte cara, y rellena el <code>Metadata.Modified</code> de cada entrada para que el orden por lo más nuevo del grupo signifique algo.</li></ul><h2 id="pinyinalias-—-alias-en-pinyin-para-nombres-de-archivo-en-chino" tabindex="-1">PinyinAlias — alias en pinyin para nombres de archivo en chino <a class="header-anchor" href="#pinyinalias-—-alias-en-pinyin-para-nombres-de-archivo-en-chino" aria-label="Permalink to &quot;PinyinAlias — alias en pinyin para nombres de archivo en chino&quot;">​</a></h2><p><code>PinyinAliasProvider</code> implementa tanto <code>IAliasProvider</code> como <code>ITranslationProvider</code> — un plugin puede combinar libremente roles del SDK cuando están relacionados, y este es un buen modelo para ello:</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> declaran sus dos alfabetos directamente a partir de los límites de la propia tabla de <code>PinyinEngine</code> (<code>InputRanges</code>: el bloque CJK; <code>OutputRanges</code>: <code>a</code>-<code>z</code>) en lugar de duplicar números mágicos — el host usa ambos juntos para admitir consultas mixtas de literal+pinyin como <code>大cj</code> contra <code>大长今</code>.</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> busca cualquier carácter chino antes de hacer trabajo real, de modo que los nombres de archivo que no son chinos se saltan por completo la generación de alias.</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> construye una tabla de sílabas por carácter (cada carácter chino se asocia a sus posibles lecturas en pinyin) y luego genera tanto un alias en pinyin completo como un alias solo de iniciales. Para nombres de archivo con caracteres polifónicos (más de una lectura válida), genera alias para cada combinación habitual — limitado a 32 combinaciones para evitar una explosión combinatoria con entradas patológicas — uniendo las alternativas con <code>|</code> para que el motor de búsqueda trate cada una como candidata en lugar de exigir que todas coincidan simultáneamente.</li><li><strong><code>ITranslationProvider</code></strong> se implementa en la <em>misma</em> clase, únicamente para proporcionar las cadenas de interfaz propias de este plugin (por ejemplo, su nombre visible) mediante <code>TranslationService.LoadEmbeddedTranslations</code> — las dos interfaces no están relacionadas en propósito, pero coinciden aquí en un mismo tipo por tratarse de un plugin pequeño, de un solo archivo.</li><li>Una caché <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> protegida por un <code>lock</code> evita volver a analizar el JSON de traducción incrustado en cada llamada — el patrón habitual para cualquier plugin que realice trabajo no trivial en <code>GetTranslations</code>.</li></ul><p>Leer ambos plugins uno junto al otro es la forma más rápida de ver cómo encajan en la práctica las piezas de la <a href="./sdk/core-search-actions.html">Referencia del SDK de Plugins</a>.</p>',9)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
